package com.bank.salstats;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class SalaryStatsDemo {
    private static final Logger log = Logger.getLogger("SalaryStats");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh", 95000.0),
            new Employee(2L, "Priya", 250000.0),
            new Employee(3L, "Amit", 120000.0),
            new Employee(4L, "Sneha", 180000.0)
        );
        SalaryStatsService service = new SalaryStatsService();
        DoubleSummaryStatistics stats = service.salarySummary(staff);
        log.info(() -> String.format(
            "count=%d sum=%.2f min=%.2f max=%.2f avg=%.2f",
            stats.getCount(), stats.getSum(), stats.getMin(), stats.getMax(), stats.getAverage()));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final double salary;
    Employee(Long id, String name, double salary) { this.id = id; this.name = name; this.salary = salary; }
    double getSalary() { return salary; }
}

// ─── Would be in service/SalaryStatsService.java ───
class SalaryStatsService {
    // One pass → count, sum, min, max, average together.
    DoubleSummaryStatistics salarySummary(List<Employee> employees) {
        return employees.stream()
            .collect(summarizingDouble(Employee::getSalary));
    }
}
